"""#,
        "marks.css": #"""
/* In a cascade layer: a layered `!important` wins over every unlayered one whatever its specificity, so a */
/* dictionary's own `li.x::before{content:"❑" !important}` (COBUILD, gallery 2026-10-16) cannot outrank XDict's. */
