:not([data-xdict-tag],[data-xdict-icon],[data-xdict-phon],[data-xdict-phon] *,[data-xdict-role=label],
[data-xdict-role=label] *,[data-xdict-sure=keep],[data-xdict-sure=keep] *,[data-xdict-sure=trans],
