[data-xdict-space=sense]{--xdict-space-want:var(--xdict-space-sense)}
[data-xdict-space=example]{--xdict-space-want:var(--xdict-space-example)}
[data-xdict-space=translation]{--xdict-space-want:var(--xdict-space-translation)}
[data-xdict-space=subhead]{--xdict-space-want:var(--xdict-space-subhead)}
[data-xdict-space=heading]{--xdict-space-want:var(--xdict-space-heading)}
[data-xdict-space=phrase]{--xdict-space-want:var(--xdict-space-phrase)}
[data-xdict-space=pos]{--xdict-space-want:var(--xdict-space-pos)}
[data-xdict-space=after-heading]{--xdict-space-want:var(--xdict-space-after-heading)}
[data-xdict-space=image]{--xdict-space-want:var(--xdict-space-image)}
/* The margin itself is column.css's, in the first cascade layer (`xdict-space`). */

